(1, 1, 'Trong Microsoft Word, tổ hợp phím nào dùng để căn đều hai bên đoạn văn bản?', 'tracnghiem', 'Ctrl + L', 'Ctrl + R', 'Ctrl + J', 'Ctrl + E', 'C', '15.00', 1, '2026-10-02 11:31:03', '2026-10-02 11:32:40'),
(2, 1, 'Trong Microsoft Excel, hàm nào dùng để đếm các ô có điều kiện?', 'tracnghiem', 'COUNT', 'COUNTA', 'COUNTIF', 'SUMIF', 'C', '15.00', 2, '2026-10-02 11:31:03', '2026-10-02 11:32:40'),
(3, 1, 'Trong hệ điều hành Windows, phím tắt nào dùng để chụp một vùng màn hình nhanh chóng?', 'tracnghiem', 'Windows + Shift + S', 'Ctrl + Alt + Del', 'Alt + Tab', 'Ctrl + Shift + Esc', 'A', '20.00', 3, '2026-10-02 11:31:03', '2026-10-02 11:32:40'),
(4, 1, 'Trình bày các giải pháp đảm bảo an toàn thông tin khi thực hiện giao dịch tài chính số tại ngân hàng và phân tích biện pháp phòng ngừa rủi ro mã độc Ransomware.', 'tuluan', NULL, NULL, NULL, NULL, NULL, '50.00', 4, '2026-10-02 11:31:03', '2026-10-02 11:32:40'),
(5, 3, 'Choose the best word to complete: \"The central bank decided to ______ the interest rates by 0.5%.\"', 'tracnghiem', 'reduce', 'fall', 'drop down', 'low', 'A', '25.00', 1, '2026-10-02 11:31:03', '2026-10-02 11:32:40'),
(6, 3, 'Choose the correct sentence:', 'tracnghiem', 'If customers deposit money today, they received bonuses.', 'If customers deposit money today, they will receive bonuses.', 'If customers deposited money today, they will receive bonuses.', 'If customers deposit money today, they would have received bonuses.', 'B', '25.00', 2, '2026-10-02 11:31:03', '2026-10-02 11:32:40'),
(7, 3, 'Writing task: Write a formal email (120-150 words) to an international client explaining why a loan application has been approved and listing the next required procedures.', 'tuluan', NULL, NULL, NULL, NULL, NULL, '50.00', 3, '2026-10-02 11:31:03', '2026-10-02 11:32:40');
